package course.week10;
import java.net.URI;import java.net.http.*;import java.time.Duration;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.util.HexFormat;
public final class SecureQuoteClient {private final HttpClient client;private final Duration timeout;public SecureQuoteClient(HttpClient c,Duration t){client=c;timeout=t;}
 public String fetch(URI uri){try{var req=HttpRequest.newBuilder(uri).timeout(timeout).GET().build();var res=client.send(req,HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));if(res.statusCode()!=200)throw new IllegalStateException("Unexpected HTTP status: "+res.statusCode());return res.body();}catch(java.io.IOException e){throw new IllegalStateException("Network failure",e);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Request interrupted",e);}}
 public String sign(String payload,byte[] key){try{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));}catch(java.security.GeneralSecurityException e){throw new IllegalStateException("Cannot sign payload",e);}}}
